<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
$root=dirname(__DIR__,2);$jobs=$root.'/bin/fmonitor2-jobs.php';$handler=$root.'/bin/fmonitor2-job-handler.php';
assertSameValue(true,is_file($jobs)&&is_file($handler),'INTENTIONAL_RED: production Jobs CLI entrypoints exist');
$env=array_replace(getenv(),['FMONITOR_DB_NAME'=>'runtime_contract','FMONITOR_DB_USER'=>'runtime','FMONITOR_DB_PASSWORD'=>'private','FMONITOR_MIGRATION_DB_PASSWORD'=>'private-admin','FMONITOR_PROCESS_TABLE_PREFIX'=>'fm_','FMONITOR_LEGACY_TABLE_PREFIX'=>'fm_','FMONITOR_SESSION_INSTANCE'=>'contract','FMONITOR_TRUSTED_REQUEST_HOST'=>'localhost','FMONITOR_TRUSTED_REQUEST_SCHEME'=>'http','FMONITOR_RUNTIME_IMAGE'=>'registry.invalid/fmonitor2@sha256:'.str_repeat('1',64)]);
function jrcRun(array$args,array$env,string$cwd):array{$p=[];$r=proc_open($args,[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$p,$cwd,$env);if(!is_resource($r))throw new TestFailure('SETUP_FAILURE process');foreach($p as$q)stream_set_blocking($q,false);$o='';$e='';$deadline=microtime(true)+10;$exit=null;do{$o.=stream_get_contents($p[1]);$e.=stream_get_contents($p[2]);$s=proc_get_status($r);if(!$s['running']){$exit=$s['exitcode'];break;}if(microtime(true)>=$deadline){proc_terminate($r,9);throw new TestFailure('SETUP_FAILURE command timeout');}usleep(10000);}while(true);$o.=stream_get_contents($p[1]);$e.=stream_get_contents($p[2]);foreach($p as$q)fclose($q);$closed=proc_close($r);return[$exit!==null&&$exit>=0?$exit:$closed,$o,$e];}
[$exit,$default,$error]=jrcRun(['docker','compose','-f','deploy/runtime/compose.yaml','config','--services'],$env,$root);assertSameValue([0,''],[$exit,$error],'default compose resolves');assertSameValue(['db','php','web'],array_values(array_filter(explode("\n",trim($default)))),'default topology excludes deployment and jobs profiles');
[$exit,$json,$error]=jrcRun(['docker','compose','-f','deploy/runtime/compose.yaml','--profile','jobs','config','--format','json'],$env,$root);assertSameValue([0,''],[$exit,$error],'jobs compose resolves');$model=json_decode($json,true,512,JSON_THROW_ON_ERROR);foreach(['jobs-worker','jobs-scheduler']as$name){$service=$model['services'][$name]??null;assertSameValue(true,is_array($service),'jobs profile contains '.$name);assertSameValue(false,array_key_exists('ports',$service),'jobs service has no ports');assertSameValue($model['services']['php']['image'],$service['image'],'jobs service uses exact php image');assertSameValue(false,(bool)preg_match('/migrate|bootstrap|docker-bootstrap|php\s+-S|socat/i',implode(' ',(array)$service['command'])),'jobs command has no startup migration/demo');}
$source=file_get_contents($jobs).file_get_contents($handler);assertSameValue(false,(bool)preg_match('/FMONITOR_DEMO_|PILOT_ACTIVE_MANIFEST|docker-bootstrap|fmonitor2-migrate|CREATE\s+TABLE|ALTER\s+TABLE|php\s+-S|socat/i',$source),'Jobs CLI has no demo/bootstrap/migration/DDL proxy');echo "PASS: JOBS-RUNTIME-WIRING-001 resolved Compose boundary\n";
